const LABELS: &[&str] = &["24T2", "24T3", "24T2", "24T3", "24T3", "24T1353", "24T1353", "24T1353", "24T2", "24T3", "24T1353", "24T1353", "24T3", "24T34", "24T2", "24T201", "24T3", "24T3", "24T3", "24T1353", "24T3", "24T3", "24T3", "24T150", "24T3", "24T2", "24T3", "24T2", "24T138", "24T2", "24T2", "24T3", "24T1077", "24T2", "24T2", "24T2", "24T1353", "24T1353", "24T1353", "24T2"];

fn up(c: &[i64]) -> UnivariatePolynomial<Integer> {
    UnivariatePolynomial::new(c.iter().map(|&x| Integer::from(x)).collect())
}

#[test]
fn lmfdb_degree24_all_irreducible() {
    for (i, c) in POLYS.iter().enumerate() {
        assert!(
            is_irreducible_over_integers(&up(c)).unwrap(),
            "poly {} (galois {}) must be irreducible (PARI confirms)", i, LABELS[i]
        );
    }
}

#[test]
fn lmfdb_degree24_times_small_recombines() {
    let smalls: [&[i64]; 3] = [&[1, 1], &[1, 0, 1], &[1, 1, 0, 1]]; // x+1, x^2+1, x^3+x+1
    for c in POLYS.iter().take(6) {
        let big = up(c);
        for s in smalls.iter() {
            let prod = big.clone() * up(s);
            let factors = factor_over_integers(&prod).unwrap();
            let deg24: Vec<_> = factors.iter().filter(|(f, _)| f.degree() == Some(24)).collect();
            assert_eq!(deg24.len(), 1, "exactly one degree-24 factor expected");
            assert_eq!(deg24[0].0.coefficients(), big.coefficients(), "must recover the original");
            let total: usize = factors.iter().map(|(f, m)| f.degree().unwrap_or(0) * (*m as usize)).sum();
            assert_eq!(total, prod.degree().unwrap(), "factor degrees must sum");
        }
    }
}

#[test]
fn big_coefficient_linear_factor() {
    // (x - K) with K huge (BigInt) times a degree-24 irreducible: must recover both.
    let k = Integer::from(100_000_000_000i64) * Integer::from(1_000i64); // 10^14
    let linear = UnivariatePolynomial::new(vec![-k.clone(), Integer::one()]); // x - K
    let big = up(&POLYS[0]);
    let prod = big.clone() * linear.clone();
    let factors = factor_over_integers(&prod).unwrap();
    assert!(factors.iter().any(|(f, _)| f.degree() == Some(24) && f.coefficients() == big.coefficients()));
    assert!(factors.iter().any(|(f, _)| f.degree() == Some(1) && f.coefficients() == linear.coefficients()));
}
